import{_ as t,o,c as a,a2 as r}from"./chunks/framework.BGlkWkwp.js";const u=JSON.parse('{"title":"InspectorSection","description":"","frontmatter":{},"headers":[],"relativePath":"workbench/inspector-section.md","filePath":"workbench/inspector-section.md"}'),d={name:"workbench/inspector-section.md"};function n(i,e,s,c,h,l){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="inspectorsection" tabindex="-1">InspectorSection <a class="header-anchor" href="#inspectorsection" aria-label="Permalink to &quot;InspectorSection&quot;">​</a></h1><p>InspectorSection is a titled group of an inspector, which can fold.</p><h2 id="when-to-use" tabindex="-1">When to use <a class="header-anchor" href="#when-to-use" aria-label="Permalink to &quot;When to use&quot;">​</a></h2><p>Use it inside an <a href="./inspector-frame">InspectorFrame</a> to group the rows of one tab: the fill, the stroke, the label of the thing shown. Put <a href="./inspector-row">InspectorRow</a> rows, a <a href="./field-list">FieldList</a> or an <a href="./attribute-list">AttributeList</a> straight in. Make a group <code>collapsible</code> when it is long or seldom used, so that the ones that matter stay in view. Put a small action on the whole group, such as a reset, in <code>end</code>.</p><h2 id="props" tabindex="-1">Props <a class="header-anchor" href="#props" aria-label="Permalink to &quot;Props&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Prop</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>title</code></td><td>required</td><td>The name of the group</td></tr><tr><td><code>collapsible</code></td><td><code>false</code></td><td>The group can be closed and opened</td></tr><tr><td><code>open</code></td><td><code>true</code></td><td>Whether the content shows (bindable)</td></tr><tr><td><code>ontoggle</code></td><td></td><td>Called with the new state when the chevron is pressed</td></tr><tr><td><code>end</code></td><td></td><td>Small buttons on the right of the head (a snippet)</td></tr><tr><td><code>rule</code></td><td><code>false</code></td><td>Draws a line above the group</td></tr><tr><td><code>flush</code></td><td><code>false</code></td><td>The content reaches the edges (a list, a tree)</td></tr><tr><td><code>children</code></td><td>required</td><td>The rows</td></tr></tbody></table><h2 id="contract" tabindex="-1">Contract <a class="header-anchor" href="#contract" aria-label="Permalink to &quot;Contract&quot;">​</a></h2><p>A <a href="./../components/section-header">SectionHeader</a>: the head is the title as a label, with the actions of <code>end</code> and then the chevron on the right, which overlap it without adding height. The chevron is a small ghost button named by the <code>expand</code> or <code>collapse</code> message, with <code>aria-expanded</code>; it points down while the group is open and right while it is closed. Closed, only the head remains, and the next group follows it as it would follow any group. The content has pad-md on its sides and below, its rows gap-sm apart. Sections are stacked with gap 0.</p><h2 id="example" tabindex="-1">Example <a class="header-anchor" href="#example" aria-label="Permalink to &quot;Example&quot;">​</a></h2><figure class="kata-example"><iframe src="/kata/examples/inspector-section/" title="InspectorSection" loading="lazy" style="width:100%;height:32rem;border:1px solid var(--vp-c-divider);border-radius:8px;"></iframe><figcaption><a href="/kata/examples/inspector-section/" target="_blank" rel="noopener">InspectorSection</a></figcaption></figure>',10)])])}const f=t(d,[["render",n]]);export{u as __pageData,f as default};
